struct Failure:std::runtime_error {int status;Failure(int status,const std::string& text):std::runtime_error(text),status(status){}};
void message(char* output,uint64_t capacity,const std::string& text){if(output&&capacity){const auto n=std::min<uint64_t>(capacity-1,text.size());std::memcpy(output,text.data(),n);output[n]=0;}}
struct Work {const penta_cas_host_v1& host;uint64_t maximum,used=0,pending=0;void flush(){if(host.cancelled&&host.cancelled(host.context))throw Failure(PENTA_NUMERIC_CANCELLED,"Native symbolic calculation cancelled.");if(pending&&host.charge){char error[512]{};if(host.charge(host.context,pending,error,sizeof(error)))throw Failure(7,error[0]?error:"Native symbolic host allowance exceeded.");}pending=0;}void tick(uint64_t n=1){if(n>maximum-used)throw Failure(7,"Native symbolic work allowance exceeded.");used+=n;pending+=n;if(pending>=256)flush();}};
struct Node;using Tree=std::shared_ptr<const Node>;
struct Node {char kind='c';Rational value=0;std::string atom,key;std::vector<Tree> children;};
bool identifier(const std::string& name){return !name.empty()&&(std::isalpha(static_cast<unsigned char>(name[0]))||name[0]=='_')&&std::all_of(name.begin()+1,name.end(),[](unsigned char c){return std::isalnum(c)||c=='_';});}
std::vector<std::string> split(const std::string& text,char delimiter){std::vector<std::string> result;std::size_t begin=0,depth=0;for(std::size_t n=0;n<=text.size();++n){if(n<text.size()){if(text[n]=='(')++depth;if(text[n]==')'){if(!depth)throw Failure(1,"Unbalanced symbolic parentheses.");--depth;}}if(n==text.size()||(text[n]==delimiter&&!depth)){auto value=text.substr(begin,n-begin);const auto first=value.find_first_not_of(" \t\r\n"),last=value.find_last_not_of(" \t\r\n");if(first!=std::string::npos)result.push_back(value.substr(first,last-first+1));else if(n!=text.size()||begin)throw Failure(1,"Empty symbolic field.");begin=n+1;}}if(depth)throw Failure(1,"Unclosed symbolic parentheses.");return result;}
