    Tree power(Tree a,long long exponent){if(exponent < -32||exponent>32)throw Failure(1,"Symbolic powers require integer exponents in[-32,32].");if(exponent<0)return divide(constant(1),power(a,-exponent));Tree result=constant(1);for(long long n=0;n<exponent;++n)result=mul(result,a);return result;}
