    Tree derivative(const Tree& value,const std::string& variable,std::size_t depth=0){work.tick();if(depth>128)throw Failure(7,"Symbolic derivative nesting exceeds128.");if(value->kind=='c')return constant(0);if(value->kind=='v')return constant(value->atom==variable?1:0);const auto a=value->children[0],da=derivative(a,variable,depth+1);if(value->kind=='+')return add(da,derivative(value->children[1],variable,depth+1));if(value->kind=='-')return add(da,derivative(value->children[1],variable,depth+1),-1);if(value->kind=='*')return add(mul(da,value->children[1]),mul(a,derivative(value->children[1],variable,depth+1)));if(value->kind=='/')return divide(add(mul(da,value->children[1]),mul(a,derivative(value->children[1],variable,depth+1)),-1),power(value->children[1],2));if(value->kind=='f'){if(!formal(value->atom)&&is(da,0))return constant(0);if(formal(value->atom)){Tree result=constant(0);for(std::size_t n=0;n<value->children.size();++n)result=add(result,mul(function(value->atom+"__d"+std::to_string(n+1),value->children),derivative(value->children[n],variable,depth+1)));return result;}if(complex&&(value->atom=="sqrt"||value->atom=="log"))branchCuts.insert(a->key);Tree factor;if(value->atom=="sin")factor=function("cos",{a});else if(value->atom=="cos")factor=mul(constant(-1),function("sin",{a}));else if(value->atom=="exp")factor=value;else if(value->atom=="sinh")factor=function("cosh",{a});else if(value->atom=="cosh")factor=function("sinh",{a});else if(value->atom=="log")factor=divide(constant(1),a);else factor=divide(constant(1),mul(constant(2),function("sqrt",{a})));return mul(factor,da);}throw Failure(1,"Unknown symbolic node.");}
